package com.holidayroster.availability.domain;
import jakarta.persistence.*; import java.time.*; import java.util.Objects;
@Entity @Table(name="availability_record") public class AvailabilityRecord {
 public enum Type { AVAILABLE, UNAVAILABLE } public enum Status { ACTIVE, CANCELLED, SUPERSEDED } @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="employee_id",nullable=false) private Long employeeId; @Enumerated(EnumType.STRING) @Column(name="availability_type",nullable=false,length=20) private Type availabilityType; @Column(name="start_date",nullable=false) private LocalDate startDate; @Column(name="end_date",nullable=false) private LocalDate endDate; @Column(name="reason_code",length=40) private String reasonCode; @Column(name="employee_note",length=500) private String note; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private Status status; @Column(name="created_at_utc",nullable=false,updatable=false) private Instant createdAtUtc; @Column(name="updated_at_utc",nullable=false) private Instant updatedAtUtc; @Version @Column(name="row_version",nullable=false) private long rowVersion;
 protected AvailabilityRecord(){} public AvailabilityRecord(Long e,Type t,LocalDate s,LocalDate end,String reason,String note,Instant now){employeeId=Objects.requireNonNull(e);createdAtUtc=updatedAtUtc=Objects.requireNonNull(now);status=Status.ACTIVE;apply(t,s,end,reason,note);} public void update(Type t,LocalDate s,LocalDate end,String reason,String note,Instant now){if(status!=Status.ACTIVE)throw new IllegalArgumentException("Only active availability can be updated.");apply(t,s,end,reason,note);updatedAtUtc=now;} public void withdraw(Instant now){if(status!=Status.ACTIVE)throw new IllegalArgumentException("Only active availability can be withdrawn.");status=Status.CANCELLED;updatedAtUtc=now;} private void apply(Type t,LocalDate s,LocalDate e,String r,String n){if(t==null||s==null||e==null||e.isBefore(s))throw new IllegalArgumentException("availabilityType and a valid inclusive date interval are required.");if(r!=null&&r.length()>40||n!=null&&n.length()>500)throw new IllegalArgumentException("Availability text exceeds its maximum length.");availabilityType=t;startDate=s;endDate=e;reasonCode=r;note=n;} public Long getId(){return id;}public Long getEmployeeId(){return employeeId;}public Type getAvailabilityType(){return availabilityType;}public LocalDate getStartDate(){return startDate;}public LocalDate getEndDate(){return endDate;}public String getReasonCode(){return reasonCode;}public String getNote(){return note;}public Status getStatus(){return status;}public long getRowVersion(){return rowVersion;}}
